import {studioRoute,unitRoute,sharedCollection,STUDIO_KEY,validateStudioNotes,decodeStudioBackup} from './studio-core.js?v=2.5.1';
import {namedGrammar} from './library.js?v=2.5.1';
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let notes={},pending=null,currentUnit=null,filter='',collection=[],lastRoute='',lastWriter='clara',requestedScroll=null,loadingFrame=false;
try{const old=JSON.parse(localStorage.getItem(STUDIO_KEY)||'{}');if(validateStudioNotes(old))notes=old;}catch{}
function toast(text){$('#studio-status').textContent=text;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#studio-status').textContent='',5000);}
function save(){try{localStorage.setItem(STUDIO_KEY,JSON.stringify(notes));}catch{toast('Dein Browser konnte die Notiz nicht speichern. Sichere dein Journal als Datei.');}}
function field(key,label,placeholder=''){return `<label class="field" for="studio-${key}">${esc(label)}</label><textarea id="studio-${key}" data-studio-note="${key}" maxlength="30000" placeholder="${esc(placeholder)}">${esc(notes[key]||'')}</textarea>`;}
function modal(html){$('#studio-dialog-content').innerHTML=html;$('#studio-dialog').showModal();}
$('.dialog-close').onclick=()=>$('#studio-dialog').close();
function home(){return `
<section class="studio-hero editorial-intro">
 <p class="eyebrow">Zwischen den Zeilen</p>
 <h1>Clara Lösel &amp; Bodo Wartke</h1>
 <p class="intro">Gedichte, Lieder und eine Werkstatt für eigene Texte.</p>
</section>
<section class="artist-grid" aria-label="Clara Lösel und Bodo Wartke">
 <article class="artist-card clara"><p class="eyebrow">Gedichte und Reels</p><h2>Clara Lösel</h2>
 <a class="artist-photo" href="#clara/inspiration"><img src="assets/clara-loesel-offiziell.jpg" alt="Clara Lösel mit einem Notizbuch" fetchpriority="high"></a>
 <p>In ihren Reels trägt Clara Lösel Gedichte über Liebe, Selbstwert und Gesellschaft vor. Hier stehen auch Texte aus ihrem Buch und Gespräche über das Schreiben.</p>
 <div class="actions"><a class="button primary" href="#clara/inspiration">Gedichte und Reels</a><a class="button" href="#schreiben/clara">Schreiben</a></div></article>
 <article class="artist-card wartke"><p class="eyebrow">Lieder und Zungenbrecher</p><h2>Bodo Wartke</h2>
 <a class="artist-photo" href="#wartke/start"><img src="https://i.ytimg.com/vi/hT42JFmxHII/hqdefault.jpg" alt="Bodo Wartke und Marti Fischer im Video Barbaras Rhabarberbar" fetchpriority="high" referrerpolicy="no-referrer"><span>Barbaras Rhabarberbar · Video ansehen</span></a>
 <p>Bei Bodo Wartke wird aus einem Zungenbrecher ein Lied. Neben den Sprachspielen gibt es Raps über Zellbiologie und Lieder über Politik, Religion und Umwelt.</p>
 <div class="actions"><a class="button primary" href="#wartke/start">Lieder und Videos</a><a class="button" href="#schreiben/wartke">Schreiben</a></div></article>
</section>
<nav class="editorial-links" aria-label="Weitere Bereiche"><a href="#wartke/form">Metrik und Rhythmus</a><a href="#vergleich">Lösel und Wartke vergleichen</a><a href="#sammlung">Gespeicherte Grammatiken</a></nav>
<details class="sentence-study"><summary>Ein Satz, drei Fassungen</summary><section class="line-lab" aria-label="Drei Fassungen eines Satzes"><p class="line-original">«Ich kann nicht schlafen.»</p><div id="live-line" class="live-line" aria-live="polite"></div><div class="line-tools" role="group" aria-label="Fassung auswählen"><button data-line="bild" aria-pressed="true">Eine Szene</button><button data-line="wiederholung" aria-pressed="false">Wiederholung</button><button data-line="wendung" aria-pressed="false">Anderer Schluss</button></div><p id="line-feedback" class="line-feedback"></p><button id="write-live-line">Im Textfeld öffnen</button><p class="small">Beispiele dieser Website.</p></section></details>
<section class="section-gap"><h2>Notizen</h2>${field('start','Ein Satz, ein Wort oder eine Idee','')}<div class="actions"><button id="start-clara">In Lösels Werkstatt öffnen</button><button id="start-wartke">In Wartkes Werkstatt öffnen</button></div></section>`;}
const lines={bild:{text:'Der Kühlschrank brummt.\nIch liege wach.',hint:'Aus der allgemeinen Aussage wird eine Szene mit einem Geräusch.'},wiederholung:{text:'Ich zähle Schritte im Treppenhaus.\nIch zähle Autos vor dem Fenster.\nIch zähle keine Schafe.',hint:'Die Zeilen beginnen gleich. In der dritten wird die bekannte Redewendung wörtlich genommen.'},wendung:{text:'Ich wollte früh ins Bett.\nJetzt weiss ich, wann der erste Bus fährt.',hint:'Der Schluss verrät, wie lange die Nacht geworden ist.'}};
function startWriting(unit,text){if(!text.trim())return toast('Schreibe zuerst ein Wort oder wähle eine Zeile.');pending={type:'lyrik:prompt',text};location.hash='#schreiben/'+unit;}
function bindHome(){let chosen='bild';const draw=()=>{$('#live-line').innerHTML=lines[chosen].text.split('\n').map(line=>line.split(' ').map((word,i)=>`<span style="animation-delay:${i*.025}s">${esc(word)}</span>`).join(' ')).join('<br>');$('#line-feedback').textContent=lines[chosen].hint;document.querySelectorAll('[data-line]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.line===chosen)));};document.querySelectorAll('[data-line]').forEach(b=>b.onclick=()=>{chosen=b.dataset.line;draw();});$('#write-live-line').onclick=()=>startWriting('clara',lines[chosen].text);$('#start-clara').onclick=()=>startWriting('clara',$('#studio-start').value);$('#start-wartke').onclick=()=>startWriting('wartke',$('#studio-start').value);draw();}
function comparison(){return `<p class="eyebrow">Clara Lösel und Bodo Wartke</p><h1>Texte vergleichen</h1><p class="intro">Was fällt dir bei den beiden auf? Hier kannst du Stellen und eigene Versuche nebeneinander festhalten.</p><div class="studio-grid"><section class="panel"><h2>Clara Lösel</h2><p>Welches Bild oder welche Wendung fällt dir auf? Notiere die Stelle.</p><a href="#clara/inspiration">Gedichte und Reels auswählen</a>${field('vergleich-clara','Notizen zu Lösel','Titel · Zeitstelle oder Seite · sprachliche Beobachtung · Wirkung')}</section><section class="panel lilac"><h2>Bodo Wartke</h2><p>Welche Reime oder Wiederholungen fallen dir auf? Was erinnerst du nach dem Hören?</p><a href="#wartke/hoeren">Hörbeispiel auswählen</a>${field('vergleich-wartke','Notizen zu Wartke','Titel · Zeitstelle · sprachliche Beobachtung · fachlicher Kern')}</section><section class="panel gold"><h2>Eigene Fassungen</h2><p>Schreibe vier Zeilen mit einem Bild oder einer Wendung. Schreibe dann vier Zeilen, die einen überprüften Zusammenhang merkbar machen. Was muss jeweils erhalten bleiben?</p>${field('vergleich-eigen','Dein Thema und deine Versuche','Du kannst über denselben Gegenstand ganz verschieden schreiben.')}<div class="actions"><button id="compare-write-clara">In Lösels Werkstatt öffnen</button><button id="compare-write-wartke">In Wartkes Werkstatt öffnen</button></div></section></div><section class="panel"><h2>Nach dem Überarbeiten</h2>${field('vergleich-rueckblick','Was hast du geändert?','Welche Form hat dir geholfen? Was ging beim Umformulieren verloren? Was prüfst du an einer Fachquelle oder am Originaltext?')}</section>`;}
function collectionPage(){return `<p class="eyebrow">Gespeicherte Grammatiken</p><h1>Sammlung</h1><p class="intro">Gespeicherte Grammatiken aus beiden Werkstätten.</p><div class="collection-controls"><div><label class="field" for="collection-search">Name, Wort oder Wendung suchen</label><input type="text" id="collection-search" value="${esc(filter)}"></div><div><label class="field" for="collection-target">Öffnen in</label><select id="collection-target"><option value="clara">Clara Lösel</option><option value="wartke">Bodo Wartke</option></select></div></div><button id="collection-refresh">Sammlung neu einlesen</button><p id="collection-status" class="connection" style="margin-top:18px" role="status"></p><div id="collection-list" class="collection-grid"></div>`;}
function readCollection(){try{const result=sharedCollection(localStorage.getItem('zwischen-zeilen-v1'),localStorage.getItem('wartke-form-gedaechtnis-v1'));collection=result.entries;$('#collection-status').textContent=result.errors.join(' ');drawCollection();}catch(error){$('#collection-status').textContent=error.message;}}
function drawCollection(){const query=filter.toLocaleLowerCase('de'),found=collection.map((e,i)=>({...e,index:i})).filter(e=>(e.grammar.name+' '+e.grammar.rules+' '+e.grammar.words).toLocaleLowerCase('de').includes(query));$('#collection-list').innerHTML=found.length?found.map(e=>`<article class="panel collection-card"><p class="eyebrow">${e.unit==='clara'?'Clara Lösel':'Bodo Wartke'}</p><h2>${esc(e.grammar.name)}</h2><p class="small">${esc(e.origins.join(' · '))}</p><details><summary>Regeln und Wörter ansehen</summary><p class="small">Startsymbol: ${esc(e.grammar.start)} · ${e.grammar.count} Erzeugungen</p><pre>${esc(e.grammar.rules)}</pre><pre>${esc(e.grammar.words)}</pre></details><div class="actions"><button class="primary" data-collection="${e.index}">In der Schreibwerkstatt öffnen</button></div></article>`).join(''):'<section class="panel"><h2>Noch keine Grammatik gespeichert</h2><p>Hier erscheinen deine gespeicherten Grammatiken und Editorentwürfe.</p><a class="button" href="#schreiben/clara?editor=regeln">Mit einer Grammatik anfangen</a></section>';document.querySelectorAll('[data-collection]').forEach(button=>button.onclick=()=>{pending={type:'lyrik:grammar',grammar:namedGrammar(collection[Number(button.dataset.collection)].grammar)};location.hash='#schreiben/'+$('#collection-target').value+'?editor=regeln';});}
function toolbar(route){const writing=route.hash.startsWith('#werkstatt'),name=route.unit==='clara'?'Clara Lösel':'Bodo Wartke';return `<section class="unit-toolbar ${writing?'is-writing':'unit-overview'}"><p>${writing?'Schreiben':name+' · Originale und eigene Versuche'}</p><nav class="unit-tabs" aria-label="${writing?'Schreibweise':'Weitere Zugänge'}">${writing?`<a href="#schreiben/clara" ${route.unit==='clara'?'aria-current="page"':''}>Clara Lösel</a><a href="#schreiben/wartke" ${route.unit==='wartke'?'aria-current="page"':''}>Bodo Wartke</a><a href="#sammlung">Meine Sammlung</a>`:`<a href="#${route.unit}/${route.unit==='clara'?'inspiration':'hoeren'}">Originale hören</a><a href="#schreiben/${route.unit}">Selbst schreiben</a><a href="#vergleich">Beide verbinden</a>`}</nav></section>`;}
function unitPage(route){currentUnit=route.unit;lastWriter=route.unit;const name=route.unit==='clara'?'Clara Lösel':'Bodo Wartke';return toolbar(route)+`<iframe id="unit-frame" class="unit-frame" title="${esc(name)} in der gemeinsamen Lyrikwerkstatt" src="${route.unit==='clara'?'clara.html':'bodo/'}?integriert=1&amp;v=2.5.1${esc(route.hash)}" scrolling="no"></iframe>`;}
function render(){requestedScroll=null;loadingFrame=false;lastRoute=location.hash;const route=studioRoute(location.hash);currentUnit=null;$('#main').innerHTML=route.page==='start'?home():route.page==='sammlung'?collectionPage():route.page==='vergleich'?comparison():unitPage(route);paintNav();document.querySelectorAll('[data-studio-note]').forEach(input=>input.oninput=()=>{notes[input.dataset.studioNote]=input.value;save();});if(route.page==='start')bindHome();if(route.page==='vergleich'){$('#compare-write-clara').onclick=()=>startWriting('clara',$('#studio-vergleich-eigen').value);$('#compare-write-wartke').onclick=()=>startWriting('wartke',$('#studio-vergleich-eigen').value);}if(route.page==='sammlung'){$('#collection-search').oninput=event=>{filter=event.target.value;drawCollection();};$('#collection-refresh').onclick=readCollection;readCollection();}if(route.page==='unit'){loadingFrame=true;$('#unit-frame').addEventListener('load',()=>{loadingFrame=false;$('#unit-frame').dataset.fullyLoaded='yes';sendPending();if(requestedScroll===null)window.scrollTo(0,0);else scrollToChild(requestedScroll);});}}
function paintNav(){const route=studioRoute(location.hash);document.querySelectorAll('.studio-nav a').forEach(a=>{const href=a.getAttribute('href');if(href.startsWith('#schreiben/'))a.href='#schreiben/'+lastWriter;const key=a.getAttribute('href').slice(1),writing=route.page==='unit'&&route.hash.startsWith('#werkstatt'),active=route.page===key||(route.page==='unit'&&(key.startsWith('schreiben/')?writing:key.startsWith(route.unit+'/')&&!writing));if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});}
function headerHeight(){return getComputedStyle($('.studio-header')).position==='sticky'?$('.studio-header').getBoundingClientRect().height:0;}
function scrollToChild(top){const frame=$('#unit-frame');if(frame)window.scrollTo({top:Math.max(0,frame.getBoundingClientRect().top+scrollY+top-headerHeight()-16),behavior:'instant'});}
function postViewport(){const frame=$('#unit-frame');if(frame)frame.contentWindow.postMessage({type:'lyrik:viewport',top:Math.max(0,scrollY+headerHeight()-(frame.getBoundingClientRect().top+scrollY)),height:innerHeight-headerHeight()},location.origin);}
window.addEventListener('scroll',postViewport,{passive:true});window.addEventListener('resize',postViewport);
function sendPending(){postViewport();const frame=$('#unit-frame');if(frame&&pending){frame.contentWindow.postMessage(pending,location.origin);pending=null;}}
window.addEventListener('message',event=>{const frame=$('#unit-frame'),data=event.data;if(!frame||event.origin!==location.origin||event.source!==frame.contentWindow||!data||data.unit!==currentUnit&&data.type!=='lyrik:grammar-opened'&&data.type!=='lyrik:error')return;
 if(data.type==='lyrik:height'&&Number.isFinite(data.height)){frame.style.height=Math.max(500,Math.min(60000,data.height))+'px';postViewport();if(loadingFrame&&requestedScroll!==null)scrollToChild(requestedScroll);}
 if(data.type==='lyrik:route'&&typeof data.hash==='string'){history.replaceState(null,'',unitRoute(currentUnit,data.hash));lastRoute=location.hash;lastWriter=currentUnit;paintNav();$('.unit-toolbar').outerHTML=toolbar(studioRoute(location.hash));postViewport();}
 if(data.type==='lyrik:open'&&['clara','wartke'].includes(data.target))location.hash=unitRoute(data.target,data.hash);
 if(data.type==='lyrik:scroll'&&Number.isFinite(data.top)){requestedScroll=data.top;scrollToChild(data.top);}
 if(data.type==='lyrik:grammar-opened')toast('Die Kopie ist in der Schreibwerkstatt geöffnet. Dein vorheriger Regelstand lässt sich dort zurückholen.');
 if(data.type==='lyrik:error')toast(String(data.message||'Die Übernahme ist nicht möglich.').slice(0,500));
});
function download(name,text){const url=URL.createObjectURL(new Blob([text],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
$('#studio-backup').onclick=()=>{try{download('gemeinsames-lyrikjournal.json',JSON.stringify({format:'lyrik-gemeinsam',version:1,notes,clara:localStorage.getItem('zwischen-zeilen-v1'),wartke:localStorage.getItem('wartke-form-gedaechtnis-v1')},null,2));}catch(error){toast(error.message);}};
$('#studio-import').onchange=async event=>{try{const file=event.target.files[0];if(!file)return;if(file.size>20000000)throw Error('Die Sicherung darf höchstens 20 MB gross sein.');const backup=decodeStudioBackup(await file.text());modal('<h2>Gemeinsames Journal laden?</h2><p>Die Notizen, Texte und Grammatiken beider Zugänge in diesem Browser werden durch die Sicherung ersetzt. Sichere deinen aktuellen Stand vorher, wenn du ihn behalten möchtest.</p><div class="actions"><button id="backup-before-restore">Aktuellen Stand sichern</button><button id="cancel-restore">Abbrechen</button><button class="primary" id="confirm-restore">Sicherung übernehmen</button></div>');$('#backup-before-restore').onclick=$('#studio-backup').onclick;$('#cancel-restore').onclick=()=>$('#studio-dialog').close();$('#confirm-restore').onclick=()=>{const changes={'zwischen-zeilen-v1':backup.clara,'wartke-form-gedaechtnis-v1':backup.wartke,[STUDIO_KEY]:JSON.stringify(backup.notes)},before={};try{for(const key of Object.keys(changes))before[key]=localStorage.getItem(key);$('#unit-frame')?.remove();for(const [key,value] of Object.entries(changes))if(value===null)localStorage.removeItem(key);else localStorage.setItem(key,value);notes=backup.notes;$('#studio-dialog').close();location.hash='#start';render();toast('Das gemeinsame Journal ist geladen.');}catch(error){for(const [key,value] of Object.entries(before)){try{if(value===null)localStorage.removeItem(key);else localStorage.setItem(key,value);}catch{}}toast('Die Sicherung konnte nicht geladen werden: '+error.message);}};}catch(error){toast(error.message);}finally{event.target.value='';}};
$('#studio-info').onclick=()=>modal('<p class="eyebrow">Clara Lösel und Bodo Wartke</p><h2>Über diese Website</h2><p>Die Sammlung enthält Entwürfe und gespeicherte Grammatiken aus beiden Werkstätten. Beim Übernehmen entsteht eine Kopie.</p><p>Unterrichtsplanung und Quellen stehen in den Bereichen zu Lösel und Wartke.</p><p>Die Beispiele sind für diese Website geschrieben. Originaltexte und Aufnahmen sind mit Quellenangaben versehen.</p><div class="actions"><a class="button" href="#clara/inspiration" id="info-clara">Lösels Originale und Quellen</a><a class="button" href="#wartke/quellen" id="info-wartke">Wartkes Quellen und Unterricht</a></div>');
$('#studio-dialog').addEventListener('click',event=>{if(event.target.closest('a[href^="#"]'))$('#studio-dialog').close();});
window.addEventListener('hashchange',()=>{if(lastRoute!==location.hash){render();$('#main').focus({preventScroll:true});window.scrollTo(0,0);}});
render();
